        super().__init__(); self.out=[]
    def handle_starttag(self, tag, attrs):
        if tag in {'p','h1','h2','h3','h4','li','pre','code','tr','br'}: self.out.append('\n')
    def handle_endtag(self, tag):
        if tag in {'p','h1','h2','h3','h4','li','pre','code','tr'}: self.out.append('\n')
    def handle_data(self,d): self.out.append(d)
p=P()
with open('/tmp/hermes-telegram.html',encoding='utf-8') as f:p.feed(f.read())
t='\n'.join(line.strip() for line in unescape(''.join(p.out)).splitlines() if line.strip())
needles=['BotFather','TELEGRAM_BOT_TOKEN','gateway setup','Dashboard','pairing','allow_from','Set Up Telegram']
for n in needles:
    print('\n###',n)
    start=0
    found=0
    while True:
        i=t.lower().find(n.lower(),start)
        if i<0 or found>=4: break
        print(t[max(0,i-500):i+1200])
        start=i+len(n);found+=1
"}

